/* Focused dynamic test for the omfile /dev/null short-circuit.
 *
 * It includes the real tools/omfile.c translation unit and calls the real
 * commitTransaction() callback. pthread_mutex_lock/unlock are interposed with
 * the linker --wrap option so the test can observe whether the write-mutex is
 * taken. The isDevNull=1 case must return success without locking; the
 * isDevNull=0 case must take and release the mutex exactly once.
 */
#include "config.h"
#include <stdio.h>
#include <string.h>

static int lock_count;
static int unlock_count;

#include "/workspace/repo/tools/omfile.c"

int __wrap_pthread_mutex_lock(pthread_mutex_t *mutex) {
    (void)mutex;
    lock_count++;
    return 0;
}

int __wrap_pthread_mutex_unlock(pthread_mutex_t *mutex) {
    (void)mutex;
    unlock_count++;
    return 0;
}

int main(void) {
    instanceData data;
    wrkrInstanceData_t wrkr;
    memset(&data, 0, sizeof(data));
    memset(&wrkr, 0, sizeof(wrkr));
    wrkr.pData = &data;

    /* /dev/null configured: must be a no-op success with no mutex traffic. */
    data.isDevNull = 1;
    lock_count = unlock_count = 0;
    rsRetVal r1 = commitTransaction(&wrkr, NULL, 0);
    printf("isDevNull=1: ret=%d lock=%d unlock=%d\n", r1, lock_count, unlock_count);
    if (r1 != RS_RET_OK || lock_count != 0 || unlock_count != 0) {
        printf("DYNAMIC TEST FAILED (devnull path)\n");
        return 1;
    }

    /* Regular file action: existing commit flow must still lock/unlock once. */
    data.isDevNull = 0;
    lock_count = unlock_count = 0;
    rsRetVal r2 = commitTransaction(&wrkr, NULL, 0);
    printf("isDevNull=0: ret=%d lock=%d unlock=%d\n", r2, lock_count, unlock_count);
    if (r2 != RS_RET_OK || lock_count != 1 || unlock_count != 1) {
        printf("DYNAMIC TEST FAILED (regular path)\n");
        return 1;
    }

    printf("DYNAMIC TEST PASSED\n");
    return 0;
}

