/* Differential baseline dynamic control: the unpatched tools/omfile.c has no
 * isDevNull short-circuit, so commitTransaction always takes the write mutex
 * even when the action is conceptually configured for /dev/null. */
#include "config.h"
#include <stdio.h>
#include <string.h>

static int lock_count;
static int unlock_count;

#include "tools/omfile.c"

int __wrap_pthread_mutex_lock(pthread_mutex_t *mutex) {
    (void)mutex;
    lock_count++;
    return 0;
}

int __wrap_pthread_mutex_unlock(pthread_mutex_t *mutex) {
    (void)mutex;
    unlock_count++;
    return 0;
}

int main(void) {
    instanceData data;
    wrkrInstanceData_t wrkr;
    memset(&data, 0, sizeof(data));
    memset(&wrkr, 0, sizeof(wrkr));
    wrkr.pData = &data;

    lock_count = unlock_count = 0;
    rsRetVal r = commitTransaction(&wrkr, NULL, 0);
    printf("baseline: ret=%d lock=%d unlock=%d (no isDevNull field/guard)\n",
           r, lock_count, unlock_count);
    if (r == RS_RET_OK && lock_count == 1 && unlock_count == 1) {
        printf("BASELINE SHOWS NO SHORT-CIRCUIT (always locks)\n");
        return 0;
    }
    printf("BASELINE UNEXPECTED\n");
    return 1;
}

