 	for(i = 0 ; i < nParams ; ++i) {
@@ -1105,6 +1111,8 @@ CODESTARTcommitTransaction
 		iRet = (pData->bDynamicName && runModConf->bDynafileDoNotSuspend) ?
 			RS_RET_OK : RS_RET_SUSPENDED;
 	}
