+terminate:
 ENDcommitTransaction


@@ -1135,6 +1143,7 @@ setInstParamDefaults(instanceData *__restrict__ const pData)
 	pData->useCryprov = 0;
 	pData->iCloseTimeout = -1;
 	pData->iSizeLimit = 0;
